window.products.push({"id":1175367,"name":"Cadence CA500 Premium PNR Pilot Aviation Headset with Aux Input and Carrying Case - Black","category":"electronics","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81-Hovh+m9L._AC_SL1500_.jpg","description":"Save your money for Avgas! The Cadence CA500 Premium PNR headset is full of features without the price. The CA500 is equipped with premium, soft, leather-type ear seals typically only found on more expensive headsets, soft integral sound dampening, and an integrated 3.5mm aux input (and free 6' aux cable!) to allow for easy music and aural feedback from your cell phone, tablet, or any device with a 3.5mm output. The headset fits perfectly in the included, custom-fitted, zippered carrying case! Designed by pilots for pilots!","images":["https://m.media-amazon.com/images/I/81-Hovh+m9L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Cadence Aviation","source_asin":"B07DR999QW","category_path":"Electronics"},"sku":"BM-1175367","productType":"Electronics","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07DR999QW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"electronics-range.jsonl","source_asin":"B07DR999QW","price_pending":true,"merchant_ready":false});
