window.products.push({"id":1175909,"name":"Intermatic IModule™ IG120RSM10K Replacement Module for Smart Guard Whole Home Surge Protector","category":"electronics","retail price":53.66,"sale price":null,"image":"https://m.media-amazon.com/images/I/61tNuG4bx8L._AC_SL1001_.jpg","description":"Intermatic's Smart Guard Surge Protective Device (SPD) uses TPMOV (Thermally Protected Metal Oxide Varistor) technology to protect your home or lite commercial environment from surges in power supply, eliminating the potentially hazardous failure modes that are commonly associated with standard MOV technology. Type 1 applications include outdoor installations before service entrances and utility meter cabinets. Type 2 applications include installations after service entrances. Installation of an Intermatic Smart Guard Surge Protective Device (SPD) provides surge protection for your entire home and all of the expensive appliances and electronic equipment inside your home, such as computers, gaming setups, home theatres and other electronic equipment. Smart Guard uses replaceable IModule with LED lights that indicate when IModule needs replacing.","images":["https://m.media-amazon.com/images/I/61tNuG4bx8L._AC_SL1001_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Intermatic","source_asin":"B00SBC0DMY","category_path":"Electronics"},"sku":"BM-1175909","productType":"Electronics","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00SBC0DMY","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"electronics-range.jsonl","source_asin":"B00SBC0DMY","price_pending":true,"merchant_ready":false});
